import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"SSL Passthrough","description":"Bypass MITM decryption for specific domains in NectoProxy.","frontmatter":{"title":"SSL Passthrough","description":"Bypass MITM decryption for specific domains in NectoProxy."},"headers":[],"relativePath":"features/ssl-passthrough.md","filePath":"features/ssl-passthrough.md","lastUpdated":1772297611000}'),n={name:"features/ssl-passthrough.md"};function s(r,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="ssl-passthrough" tabindex="-1">SSL Passthrough <a class="header-anchor" href="#ssl-passthrough" aria-label="Permalink to &quot;SSL Passthrough&quot;">​</a></h1><p>SSL Passthrough allows you to configure specific domains whose HTTPS traffic should <strong>pass through NectoProxy without being decrypted</strong>. Traffic to passthrough domains is forwarded directly to the destination server, maintaining the original end-to-end TLS encryption.</p><h2 id="what-is-ssl-passthrough" tabindex="-1">What is SSL Passthrough? <a class="header-anchor" href="#what-is-ssl-passthrough" aria-label="Permalink to &quot;What is SSL Passthrough?&quot;">​</a></h2><p>By default, NectoProxy performs <strong>Man-in-the-Middle (MITM)</strong> interception on all HTTPS traffic. This means it decrypts requests, inspects them, and re-encrypts them before forwarding. While this is necessary for traffic inspection, there are situations where you do not want (or cannot) decrypt traffic for certain domains.</p><p>SSL Passthrough tells NectoProxy to act as a <strong>transparent TCP tunnel</strong> for those domains. The proxy receives the <code>CONNECT</code> request from the client, establishes a TCP connection to the target server, and then forwards raw bytes in both directions without any decryption or inspection.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Without SSL Passthrough (default):</span></span>
<span class="line"><span>  Client &lt;--TLS--&gt; NectoProxy &lt;--TLS--&gt; Server</span></span>
<span class="line"><span>  (NectoProxy decrypts, inspects, re-encrypts)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>With SSL Passthrough:</span></span>
<span class="line"><span>  Client &lt;--TLS-------------------TLS--&gt; Server</span></span>
<span class="line"><span>  (NectoProxy tunnels raw bytes, no decryption)</span></span></code></pre></div><h2 id="when-to-use-ssl-passthrough" tabindex="-1">When to Use SSL Passthrough <a class="header-anchor" href="#when-to-use-ssl-passthrough" aria-label="Permalink to &quot;When to Use SSL Passthrough&quot;">​</a></h2><h3 id="certificate-pinning" tabindex="-1">Certificate Pinning <a class="header-anchor" href="#certificate-pinning" aria-label="Permalink to &quot;Certificate Pinning&quot;">​</a></h3><p>Some applications implement <strong>certificate pinning</strong>, where the client verifies that the server&#39;s certificate matches a specific known certificate or public key. When NectoProxy performs MITM interception, it presents its own generated certificate, which does not match the pinned certificate. This causes the connection to fail.</p><p>Adding such domains to the SSL Passthrough list allows the connection to succeed because the client sees the real server certificate.</p><div class="tip custom-block"><p class="custom-block-title">Common Pinned Domains</p><p>Mobile banking applications, certain Google services, and many native mobile apps use certificate pinning. If you see TLS connection failures for specific domains, certificate pinning is a likely cause.</p></div><h3 id="financial-and-banking-services" tabindex="-1">Financial and Banking Services <a class="header-anchor" href="#financial-and-banking-services" aria-label="Permalink to &quot;Financial and Banking Services&quot;">​</a></h3><p>Even when certificate pinning is not in use, you may want to avoid decrypting traffic to banking and financial services as a matter of security practice. SSL Passthrough ensures that sensitive financial data is never exposed in the proxy, even temporarily.</p><h3 id="compliance-requirements" tabindex="-1">Compliance Requirements <a class="header-anchor" href="#compliance-requirements" aria-label="Permalink to &quot;Compliance Requirements&quot;">​</a></h3><p>Some organizations have policies that prohibit the interception of certain types of traffic. SSL Passthrough lets you use NectoProxy for general debugging while respecting these policies for specific domains.</p><h3 id="application-level-tls-verification" tabindex="-1">Application-Level TLS Verification <a class="header-anchor" href="#application-level-tls-verification" aria-label="Permalink to &quot;Application-Level TLS Verification&quot;">​</a></h3><p>Applications that perform additional TLS verification beyond standard certificate chain validation (such as mutual TLS or custom trust stores) may fail when traffic is intercepted. SSL Passthrough ensures these applications work correctly through the proxy.</p><h2 id="configuring-ssl-passthrough" tabindex="-1">Configuring SSL Passthrough <a class="header-anchor" href="#configuring-ssl-passthrough" aria-label="Permalink to &quot;Configuring SSL Passthrough&quot;">​</a></h2><h3 id="adding-a-domain" tabindex="-1">Adding a Domain <a class="header-anchor" href="#adding-a-domain" aria-label="Permalink to &quot;Adding a Domain&quot;">​</a></h3><ol><li>Open the <strong>SSL Passthrough</strong> panel from the settings area in NectoProxy</li><li>Click <strong>Add Domain</strong></li><li>Enter the domain name or wildcard pattern</li><li>Optionally add a <strong>reason or note</strong> explaining why passthrough is configured</li><li>The entry is enabled by default</li></ol><h3 id="domain-format" tabindex="-1">Domain Format <a class="header-anchor" href="#domain-format" aria-label="Permalink to &quot;Domain Format&quot;">​</a></h3><p>SSL Passthrough entries support exact domain names and wildcard patterns:</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Matches</th><th>Does Not Match</th></tr></thead><tbody><tr><td><code>bank.example.com</code></td><td><code>bank.example.com</code></td><td><code>www.bank.example.com</code></td></tr><tr><td><code>*.example.com</code></td><td><code>www.example.com</code>, <code>api.example.com</code></td><td><code>example.com</code>, <code>sub.sub.example.com</code></td></tr><tr><td><code>*.google.com</code></td><td><code>accounts.google.com</code>, <code>mail.google.com</code></td><td><code>google.com</code></td></tr><tr><td><code>*.*.example.com</code></td><td><code>a.b.example.com</code></td><td><code>c.example.com</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Wildcard patterns match only one level of subdomain per <code>*</code>. The pattern <code>*.example.com</code> matches <code>www.example.com</code> but not <code>a.b.example.com</code>. Use <code>*.*.example.com</code> for two-level matching, or add multiple entries if you need broader coverage.</p></div><h3 id="per-domain-enable-disable" tabindex="-1">Per-Domain Enable/Disable <a class="header-anchor" href="#per-domain-enable-disable" aria-label="Permalink to &quot;Per-Domain Enable/Disable&quot;">​</a></h3><p>Each passthrough entry has an <strong>enable/disable toggle</strong>. When disabled, the domain reverts to normal MITM interception. This lets you keep entries configured for later use without removing them.</p><details class="details custom-block"><summary>Example Configuration</summary><table tabindex="0"><thead><tr><th>Domain</th><th>Reason</th><th>Enabled</th></tr></thead><tbody><tr><td><code>*.bank.example.com</code></td><td>Banking app uses certificate pinning</td><td>Yes</td></tr><tr><td><code>accounts.google.com</code></td><td>OAuth flow breaks with MITM</td><td>Yes</td></tr><tr><td><code>*.apple.com</code></td><td>Apple services certificate pinning</td><td>Yes</td></tr><tr><td><code>internal.corp.net</code></td><td>Compliance requirement</td><td>Yes</td></tr><tr><td><code>api.payment.com</code></td><td>PCI DSS compliance</td><td>Yes</td></tr><tr><td><code>*.staging.example.com</code></td><td>Temporarily disabled for debugging</td><td>No</td></tr></tbody></table></details><h3 id="adding-a-reason-note" tabindex="-1">Adding a Reason/Note <a class="header-anchor" href="#adding-a-reason-note" aria-label="Permalink to &quot;Adding a Reason/Note&quot;">​</a></h3><p>Each passthrough entry supports a free-text <strong>reason</strong> field. Use this to document why the domain is excluded from interception. This is especially valuable in team environments where multiple people may be using or administering NectoProxy.</p><p>Good examples of reasons:</p><ul><li>&quot;Banking app uses certificate pinning -- connection fails without passthrough&quot;</li><li>&quot;PCI DSS compliance requires end-to-end encryption for payment traffic&quot;</li><li>&quot;OAuth callback fails when certificate is not the original&quot;</li><li>&quot;Mobile app crashes on certificate mismatch for this domain&quot;</li></ul><h2 id="managing-passthrough-entries" tabindex="-1">Managing Passthrough Entries <a class="header-anchor" href="#managing-passthrough-entries" aria-label="Permalink to &quot;Managing Passthrough Entries&quot;">​</a></h2><h3 id="crud-operations" tabindex="-1">CRUD Operations <a class="header-anchor" href="#crud-operations" aria-label="Permalink to &quot;CRUD Operations&quot;">​</a></h3><p>The SSL Passthrough panel provides full CRUD (Create, Read, Update, Delete) operations:</p><ul><li><strong>Create</strong> -- Add new domains via the Add Domain form</li><li><strong>Read</strong> -- View all configured passthrough entries in a table</li><li><strong>Update</strong> -- Edit the domain pattern, reason, or enabled state of any entry</li><li><strong>Delete</strong> -- Remove entries that are no longer needed</li></ul><h3 id="bulk-management" tabindex="-1">Bulk Management <a class="header-anchor" href="#bulk-management" aria-label="Permalink to &quot;Bulk Management&quot;">​</a></h3><p>For situations where you need to configure many domains at once, you can add multiple domains separated by newlines in the Add Domain form.</p><h2 id="performance-benefits" tabindex="-1">Performance Benefits <a class="header-anchor" href="#performance-benefits" aria-label="Permalink to &quot;Performance Benefits&quot;">​</a></h2><p>SSL Passthrough provides a modest <strong>performance improvement</strong> for traffic to configured domains because NectoProxy skips the TLS decryption and re-encryption process:</p><ul><li><strong>No certificate generation</strong> -- NectoProxy does not need to generate a certificate for the target domain</li><li><strong>No decryption overhead</strong> -- The proxy does not perform any cryptographic operations on the traffic</li><li><strong>No inspection processing</strong> -- Traffic is not parsed, analyzed, or stored in the session</li><li><strong>Lower memory usage</strong> -- Passthrough traffic does not consume memory for request/response storage</li></ul><p>For domains that generate high volumes of traffic (such as CDNs or streaming services) that you do not need to inspect, SSL Passthrough can noticeably reduce NectoProxy&#39;s CPU and memory usage.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you are experiencing high resource usage with NectoProxy, consider adding high-traffic domains that you do not need to inspect (such as CDN domains, analytics services, or streaming endpoints) to the passthrough list.</p></div><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li><strong>No traffic inspection</strong> -- Passthrough traffic cannot be viewed, filtered, or analyzed in NectoProxy. It appears in the traffic list only as a <code>CONNECT</code> tunnel entry.</li><li><strong>No rules</strong> -- Rules Engine actions (Mock, Block, Modify, etc.) cannot be applied to passthrough traffic since the content is not decrypted.</li><li><strong>No breakpoints</strong> -- Breakpoints cannot intercept passthrough traffic.</li><li><strong>DNS resolution</strong> -- SSL Passthrough does not affect DNS resolution. Use <a href="./dns-mapping.html">DNS Mapping</a> if you need to redirect passthrough traffic to a different IP address.</li></ul><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>SSL Passthrough entries are persisted across NectoProxy sessions. Entries you configure are saved and automatically loaded the next time you start the proxy.</p></div>`,46)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
